import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.BGlkWkwp.js";const f=JSON.parse('{"title":"A panel","description":"","frontmatter":{},"headers":[],"relativePath":"patterns/panel.md","filePath":"patterns/panel.md"}'),n={name:"patterns/panel.md"};function s(i,e,l,h,p,c){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="a-panel" tabindex="-1">A panel <a class="header-anchor" href="#a-panel" aria-label="Permalink to &quot;A panel&quot;">​</a></h1><p>A panel is a side of the screen: a head with its title and actions, content in groups that scrolls, and an optional foot.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for what stays open next to the work: the contents, the properties of what is selected, a search, the comments. A task that stops the work is a <a href="./modal-form">modal</a>; a panel that slides over the page is a <a href="./../components/drawer">Drawer</a>. For the properties of the selection, the <a href="./../workbench/inspector-frame">InspectorFrame</a> is a panel with this shape already.</p><h2 id="parts" tabindex="-1">Parts <a class="header-anchor" href="#parts" aria-label="Permalink to &quot;Parts&quot;">​</a></h2><ul><li><a href="./../components/panel">Panel</a> with <code>side</code> for its width.</li><li>A <a href="./../components/toolbar">Toolbar</a> in <code>head</code>, with the title, a line along its bottom and icon buttons at the end.</li><li>The content, a <a href="./../components/stack">Stack</a> with gap 0 of <a href="./../components/section-header">SectionHeader</a> groups. A group holds fields and switches, or, with <code>flush</code>, a <a href="./../components/list">List</a> or a <a href="./../components/tree">Tree</a> that reaches the edges.</li><li>A <a href="./../components/block">Block</a> for text that is not in a group.</li><li>A <a href="./../components/footer">Footer</a> in <code>foot</code> when the panel applies its changes at once.</li></ul><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><ul><li>The content has no padding: lists and groups reach the edges and bring their own. Text and fields go in a group or a Block.</li><li>Groups are apart by their own heads, never by a gap.</li><li>The head and the foot keep their height; only the content scrolls.</li></ul><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/pattern-panel/" title="A panel" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/pattern-panel/" target="_blank" rel="noopener">A panel</a></figcaption></figure>',10)])])}const m=a(n,[["render",s]]);export{f as __pageData,m as default};
